import{_ as a,o as t,c as o,a5 as s}from"./chunks/framework.DSg0KOwT.js";const p=JSON.parse('{"title":"Apache DataFusion Comet","titleTemplate":":title | Spark Tuning Reference","description":"Apache DataFusion Comet: plugin and shared off-heap pool sizing, native/columnar shuffle, ShuffledHashJoin tradeoffs, UDF and scan fallbacks, and reading Comet plans and transitions.","frontmatter":{"title":"Apache DataFusion Comet","titleTemplate":":title | Spark Tuning Reference","description":"Apache DataFusion Comet: plugin and shared off-heap pool sizing, native/columnar shuffle, ShuffledHashJoin tradeoffs, UDF and scan fallbacks, and reading Comet plans and transitions."},"headers":[],"relativePath":"tuning-reference/native-comet.md","filePath":"tuning-reference/native-comet.md"}'),n={name:"tuning-reference/native-comet.md"};function r(i,e,c,f,l,d){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="native-comet" tabindex="-1">Apache DataFusion Comet <a class="header-anchor" href="#native-comet" aria-label="Permalink to &quot;Apache DataFusion Comet {#native-comet}&quot;">​</a></h1><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Apache DataFusion Comet is a high-performance accelerator for Apache Spark. It keeps Spark queries Arrow-native end to end: operators, expressions, shuffle and broadcast all stay in Apache Arrow columnar format<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>. Consecutive Rust-implemented operators are combined into a single block that is serialized as protobuf and executed by DataFusion on the executor<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>. The notes here follow Comet&#39;s documentation on its main branch, which is not versioned, so check them against the release you run.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>The installation guide&#39;s quick start sets <code>spark.plugins</code> to <code>org.apache.spark.CometPlugin</code>, <code>spark.shuffle.manager</code> to <code>org.apache.spark.sql.comet.execution.shuffle.CometShuffleManager</code>, <code>spark.memory.offHeap.enabled</code> to <code>true</code> with a <code>spark.memory.offHeap.size</code>, and <code>spark.executor.memoryOverhead</code>, and it turns on <code>spark.comet.explain.fallback.enabled</code> to log fallback reasons<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup>.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.plugins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=org.apache.spark.CometPlugin</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.shuffle.manager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=org.apache.spark.sql.comet.execution.shuffle.CometShuffleManager</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.comet.explain.fallback.enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.memory.offHeap.enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.memory.offHeap.size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=4g</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.executor.memoryOverhead</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2g</span></span></code></pre></div><p>Comet requires JDK 17 or later, and the installation guide recommends using it only with Spark versions where both Comet and Spark tests run in CI<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3:1]</a></sup>.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p>Comet shares an off-heap memory pool with Spark, sized by <code>spark.memory.offHeap.size</code>. The pool is a shared budget rather than a shared allocator: Comet&#39;s native operators allocate from the Rust heap, but every reservation they make is charged against the same pool as Spark&#39;s own off-heap consumers. An operator that cannot spill fails the task when it cannot reserve the memory it needs<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup>.</p><p>Memory that Comet&#39;s accounting does not track has to fit in <code>spark.executor.memoryOverhead</code>, so enabling off-heap memory is not sufficient on its own. Setting <code>spark.executor.memoryOverhead</code> replaces the derived value (<code>max(spark.executor.memoryOverheadFactor * spark.executor.memory, 384 MiB)</code>, factor <code>0.1</code>) instead of adding to it, so a value below the derived one shrinks the container. The guide gives <code>2g</code> as a reasonable start for a small executor, says to raise <code>spark.executor.memoryOverheadFactor</code> instead for large ones, and says to raise the overhead further if the cluster manager kills executors (on Kubernetes, <code>ExecutorLostFailure</code> with exit code 137)<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4:1]</a></sup>. See <a href="./memory-model.html">Memory Management</a> for how Spark sizes overhead.</p><h2 id="shuffle" tabindex="-1">Shuffle <a class="header-anchor" href="#shuffle" aria-label="Permalink to &quot;Shuffle&quot;">​</a></h2><p>Comet tries native shuffle first, then columnar shuffle, and falls back to Spark&#39;s shuffle if neither applies. <code>spark.shuffle.manager</code> is a static setting that cannot change at runtime, so Comet shuffle is toggled at runtime with <code>spark.comet.shuffle.enabled</code>. By default Comet converts a Spark <code>ShuffleExchangeExec</code> to columnar shuffle even when its child is a non-Comet plan, at the cost of a row-to-columnar conversion at the shuffle boundary, and <code>spark.comet.shuffle.convertFromSparkPlan.enabled=false</code> opts out. The codec is set with <code>spark.comet.shuffle.compression.codec</code> (<code>lz4</code> by default, <code>zstd</code> and <code>snappy</code> also supported)<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup>. The tuning rules on the <a href="./shuffle.html">Shuffle</a> page describe Spark&#39;s own shuffle.</p><h2 id="joins" tabindex="-1">Joins <a class="header-anchor" href="#joins" aria-label="Permalink to &quot;Joins&quot;">​</a></h2><p>Vectorized engines tend to perform better with <code>ShuffledHashJoin</code>, so Comet&#39;s tuning guide suggests converting <code>SortMergeJoin</code> to it with <code>spark.comet.exec.forceShuffledHashJoin=true</code>. Comet does not yet provide spill-to-disk for <code>ShuffledHashJoin</code>, so this can run out of memory<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup>. <code>BroadcastHashJoinExec</code> is supported, and <code>BroadcastNestedLoopJoinExec</code> falls back to Spark when the preserved side is broadcast<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6:1]</a></sup>. See <a href="./joins.html">Join Optimization</a> for the strategy rules on the Spark side.</p><h2 id="udfs" tabindex="-1">UDFs <a class="header-anchor" href="#udfs" aria-label="Permalink to &quot;UDFs&quot;">​</a></h2><p>The presence of a Scala or Java UDF does not force the enclosing operator out of the Comet pipeline. Python <code>@udf</code>, pandas <code>@pandas_udf</code>, aggregate and Hive UDFs are out of scope and continue to fall back to Spark<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup>. Comet can accelerate Python UDFs that use PyArrow-backed batch processing, such as <code>mapInArrow</code> and <code>mapInPandas</code><sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup>. See <a href="./pyspark.html">PySpark Specifics</a> for the UDF cost on the Spark side.</p><h2 id="scans" tabindex="-1">Scans <a class="header-anchor" href="#scans" aria-label="Permalink to &quot;Scans&quot;">​</a></h2><p>Comet falls back to Spark for Parquet scans it cannot convert. The documented cases include <code>ShortType</code> columns by default, <code>ignoreMissingFiles</code> or <code>ignoreCorruptFiles</code> set to <code>true</code>, and <code>spark.sql.parquet.enableVectorizedReader=false</code><sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup>. Pushing filter evaluation into the Parquet decode step with <code>spark.comet.parquet.rowFilterPushdown.enabled=true</code> is disabled by default because it can hurt when the filter is not selective, and the scan tuning guide&#39;s workaround for scan tasks left with no row groups is a lower <code>spark.sql.files.maxPartitionBytes</code><sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup>. See <a href="./data-formats.html">Data Formats</a> for the Spark scan.</p><h2 id="reading-the-plan" tabindex="-1">Reading the plan <a class="header-anchor" href="#reading-the-plan" aria-label="Permalink to &quot;Reading the plan&quot;">​</a></h2><p>Operators that Comet does not support remain in their original Spark form. Fallback can be partial (a subtree falls back to Spark while the rest stays in the Comet pipeline) or full (no Comet nodes appear). Wherever data crosses between columnar and row-based execution, Comet inserts a transition node such as <code>CometColumnarToRow</code> or <code>CometSparkRowToColumnar</code>, and frequent transitions usually indicate fallback inside the plan<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup>. <code>spark.comet.explain.fallback.enabled</code> logs a warning with the reasons each query stage could not run in Comet<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2:2]</a></sup>. Under AQE the report describes the plan before any adaptive re-planning, so coverage of the plan that finally executes can differ<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2:3]</a></sup>, which affects how you read it next to <a href="./aqe.html">Adaptive Query Execution</a>.</p><p>Repeated columnar-to-row and row-to-columnar conversions can dominate stage runtime. <code>spark.comet.exec.transitionRevert.enabled=true</code> reverts the whole stage to Spark row execution once the number of columnar-to-row transitions exceeds <code>spark.comet.exec.transitionRevert.maxTransitions</code> (default <code>2</code>)<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup>.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>Comet aims for results consistent with the Spark version in use and documents the areas where its behavior differs. Some expressions also have a native implementation that can differ from Spark for certain inputs, and these are not used unless you opt in with the relevant <code>spark.comet.expression.&lt;Name&gt;.allowIncompatible=true</code> setting<sup class="footnote-ref"><a href="#fn12" id="fnref12">[12]</a></sup>.</p><h2 id="confidence" tabindex="-1">Confidence <a class="header-anchor" href="#confidence" aria-label="Permalink to &quot;Confidence&quot;">​</a></h2><p>The settings, defaults and fallback cases above come from Comet&#39;s own installation guide, tuning guides and compatibility pages. Settings and their defaults can change between Comet releases, so confirm one against the release you run. The memory-sizing guidance is specific to Comet&#39;s off-heap accounting and does not replace sizing from your own executor metrics.</p><h2 id="limitations-false-positive-risk" tabindex="-1">Limitations / false-positive risk <a class="header-anchor" href="#limitations-false-positive-risk" aria-label="Permalink to &quot;Limitations / false-positive risk&quot;">​</a></h2><p>Fallback is per operator or subtree, so a plan with some Comet nodes can still run stages on the Spark engine. Because the fallback report under AQE describes the plan before adaptive re-planning<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2:4]</a></sup>, coverage in the final plan can differ from what the log lists.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/README.md" target="_blank" rel="noreferrer">Apache DataFusion Comet README</a> <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/understanding-comet-plans.md" target="_blank" rel="noreferrer">Understanding Comet plans</a> <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a> <a href="#fnref2:2" class="footnote-backref">↩︎</a> <a href="#fnref2:3" class="footnote-backref">↩︎</a> <a href="#fnref2:4" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/installation.md" target="_blank" rel="noreferrer">Comet installation guide</a> <a href="#fnref3" class="footnote-backref">↩︎</a> <a href="#fnref3:1" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/tuning/memory.md" target="_blank" rel="noreferrer">Comet memory tuning</a> <a href="#fnref4" class="footnote-backref">↩︎</a> <a href="#fnref4:1" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/tuning/shuffle.md" target="_blank" rel="noreferrer">Comet shuffle tuning</a> <a href="#fnref5" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/tuning/operators.md" target="_blank" rel="noreferrer">Comet operator tuning</a> <a href="#fnref6" class="footnote-backref">↩︎</a> <a href="#fnref6:1" class="footnote-backref">↩︎</a></p></li><li id="fn7" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/scala_java_udfs.md" target="_blank" rel="noreferrer">Comet Scala and Java UDFs</a> <a href="#fnref7" class="footnote-backref">↩︎</a></p></li><li id="fn8" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/pyarrow-udfs.md" target="_blank" rel="noreferrer">Comet PyArrow UDFs</a> <a href="#fnref8" class="footnote-backref">↩︎</a></p></li><li id="fn9" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/compatibility/scans.md" target="_blank" rel="noreferrer">Comet scan compatibility</a> <a href="#fnref9" class="footnote-backref">↩︎</a></p></li><li id="fn10" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/tuning/scans.md" target="_blank" rel="noreferrer">Comet scan tuning</a> <a href="#fnref10" class="footnote-backref">↩︎</a></p></li><li id="fn11" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/tuning/transitions.md" target="_blank" rel="noreferrer">Comet transition tuning</a> <a href="#fnref11" class="footnote-backref">↩︎</a></p></li><li id="fn12" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/datafusion-comet/main/docs/source/user-guide/latest/compatibility/index.md" target="_blank" rel="noreferrer">Comet compatibility guide</a> <a href="#fnref12" class="footnote-backref">↩︎</a></p></li></ol></section>`,30)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
